-- LOCAL disposable fixture, transaction rollback. No real data or network services.
reset role;
create temp table so_before as select jsonb_build_object('entries',(select jsonb_agg(to_jsonb(e) order by id) from public.position_evaluation_entries e),
 'assessments',(select jsonb_agg(to_jsonb(a) order by id) from public.position_assessments a),'attempts',(select jsonb_agg(to_jsonb(a) order by id) from public.position_assessment_attempts a),
 'scores',(select jsonb_agg(to_jsonb(a) order by id) from public.match_evaluations a),'profiles',(select jsonb_agg(to_jsonb(a) order by id) from public.professional_profiles a)) value;
create temp table so_state as select id,revision from public.position_evaluation_processes where vacancy_id=m83_id('sp-vac') and is_current;
grant all on so_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_assert(public.get_selection_process_workspace(m83_id('a'),'', 'all',0,(select (value#>>'{process,id}')::uuid from sp_result))#>'{selected,outcome}'='null','legacy closure never invents an outcome');
select m83_assert(public.get_person_selection_history(m83_id('a'),m83_id('person'))->>'contract'='person-selection-history-1.0.0','versioned scoped person history');
select m83_assert(jsonb_array_length(public.get_person_selection_history(m83_id('a'),m83_id('person'))->'legacyTests')>0,'legacy individual tests remain accessible without guessed process');
select m83_reject(format('select public.get_person_selection_history(%L,%L,-1)',m83_id('a'),m83_id('person')),'22023');
select m83_reject(format('select public.get_person_selection_history(%L,%L)',m83_id('b'),m83_id('person')),'42501');
select m83_reject(format('select public.get_person_selection_history(%L,%L)',m83_id('a'),m83_id('unknown-person')),'42501');
select set_config('request.jwt.claim.sub',m83_id('member')::text,true);
select m83_reject(format('select public.get_person_selection_history(%L,%L)',m83_id('a'),m83_id('person')),'42501');
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state),'{"contract":"selection-process-outcome-1.0.0","outcome":"none"}'),'42501');
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state)),'22023');
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state),'{"contract":"unknown","outcome":"none"}'),'22023');
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state),jsonb_build_object('contract','selection-process-outcome-1.0.0','outcome','selected','selectedPersonId',m83_id('person'))),'22023');
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state),jsonb_build_object('contract','selection-process-outcome-1.0.0','outcome','none','selectedPersonId',m83_id('person'))),'22023');
select m83_assert(public.get_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state))#>>'{process,status}'='active','invalid/unknown closures preserve active process');
select m83_assert(public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'close_process',null,(select revision from so_state),'{"contract":"selection-process-outcome-1.0.0","outcome":"none"}')#>>'{process,outcome,outcome}'='none','empty process explicitly closes without choice');
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state),'{"contract":"selection-process-outcome-1.0.0","outcome":"none"}'),'40001');
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'reopen_process',null,(select revision+1 from so_state));
select m83_assert(public.get_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state))#>'{process,outcome}'='null','reopening removes current choice and preserves closure audit');
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'add',m83_id('person'),null,jsonb_build_object('profileId',m83_id('profile'),'positionId',m83_id('sp-ver')));
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'details',m83_id('person'),1,'{"notes":"Atividade sintética registrada","nextAction":"Conferir avaliação"}');
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''decision'',%L,2,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),m83_id('person'),'{"outcome":"selected","rationale":"Not allowed before closure"}'),'22023');
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'decision',m83_id('person'),2,'{"outcome":"proceed","rationale":"Decisão intermediária sintética"}');
select m83_assert(public.get_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state))#>'{process,outcome}'='null','proceed is not final selection');
reset role;
update so_state set revision=(select revision from public.position_evaluation_processes where id=so_state.id);
insert into public.people(id,organization_id,full_name) values(m83_id('so-other'),m83_id('a'),'Outra Pessoa sintética');
insert into public.professional_profiles(id,organization_id,person_id,profile_data,extraction_version,inference_version,embedding_version,prompt_version,model_version,profile_version,review_status,approved_at)
 values(m83_id('so-other-profile'),m83_id('a'),m83_id('so-other'),'{}','fixture','none','none','fixture','fixture',1,'approved',now());
update so_before set value=jsonb_set(value,'{profiles}',(select jsonb_agg(to_jsonb(a) order by id) from public.professional_profiles a));
set local role authenticated;
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'add',m83_id('so-other'),null,jsonb_build_object('profileId',m83_id('so-other-profile'),'positionId',m83_id('sp-ver')));
reset role;
update so_state set revision=(select revision from public.position_evaluation_processes where id=so_state.id);
create function public.so_reject_closure_audit() returns trigger language plpgsql as $$ begin if new.action='close_process' then raise exception 'Synthetic audit failure'; end if; return new; end $$;
create trigger so_audit_failure before insert on public.position_evaluation_history for each row execute function public.so_reject_closure_audit();
set local role authenticated;
select m83_reject(format('select public.mutate_position_follow_up_process(%L,%L,%L,''close_process'',null,%s,%L::jsonb)',m83_id('a'),m83_id('sp-vac'),(select id from so_state),(select revision from so_state),jsonb_build_object('contract','selection-process-outcome-1.0.0','outcome','selected','selectedPersonId',m83_id('person'))),'P0001');
select m83_assert(public.get_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state))#>>'{process,status}'='active' and public.get_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state))#>'{process,outcome}'='null','audit failure rolls back both closure and choice');
reset role;
drop trigger so_audit_failure on public.position_evaluation_history;
drop function public.so_reject_closure_audit();
create temp table so_entries_before as select jsonb_agg(to_jsonb(e) order by id) value from public.position_evaluation_entries e;
set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_assert(public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'close_process',null,(select revision from so_state),jsonb_build_object('contract','selection-process-outcome-1.0.0','outcome','selected','selectedPersonId',m83_id('person')))#>>'{process,outcome,selectedPersonId}'=m83_id('person')::text,'valid participant selected atomically with closure');
select m83_assert(public.get_selection_process_workspace(m83_id('a'),'', 'all',0,(select id from so_state))#>>'{selected,outcome,outcome}'='selected','workspace exposes human closure result');
select m83_assert(exists(select 1 from jsonb_array_elements(public.get_person_selection_history(m83_id('a'),m83_id('person'))->'participations') p where p->>'processId'=(select id::text from so_state) and p#>>'{outcome,selectedPersonId}'=m83_id('person')::text),'person history exposes exact choice and cycle');
select m83_assert(jsonb_array_length(public.get_person_selection_history(m83_id('a'),m83_id('person'))->'participations')>=2,'historical cycles never overwritten by current pointer');
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'reopen_process',null,(select revision+1 from so_state));
select m83_assert(exists(select 1 from jsonb_array_elements(public.get_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state))->'history') h where h->>'action'='close_process' and h#>>'{after,closureOutcome}'='selected' and h->>'subjectName' is not null),'past chosen participant remains in history after reopening');
reset role;
select m83_assert((select value from so_entries_before)=(select jsonb_agg(to_jsonb(e) order by id) from public.position_evaluation_entries e),'closure and reopening preserve all participant data and stages');
select m83_assert((select value-'entries' from so_before)=jsonb_build_object('assessments',(select jsonb_agg(to_jsonb(a) order by id) from public.position_assessments a),'attempts',(select jsonb_agg(to_jsonb(a) order by id) from public.position_assessment_attempts a),'scores',(select jsonb_agg(to_jsonb(a) order by id) from public.match_evaluations a),'profiles',(select jsonb_agg(to_jsonb(a) order by id) from public.professional_profiles a)),'assessment answer result Score and Profile snapshots preserved');
select m83_assert((select status='vacant' and occupant_person_id is null from public.positions where id=m83_id('sp-pos')),'selection never occupies position');
set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'close_process',null,(select revision+2 from so_state),'{"contract":"selection-process-outcome-1.0.0","outcome":"none"}');
select m83_assert(exists(select 1 from jsonb_array_elements(public.get_person_selection_history(m83_id('a'),m83_id('person'))->'participations') p where p->>'processId'=(select id::text from so_state) and p#>>'{outcome,outcome}'='none'),'closure without choice with participants has explicit result in person history');
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'reopen_process',null,(select revision+3 from so_state));
select public.mutate_position_follow_up_process(m83_id('a'),m83_id('sp-vac'),(select id from so_state),'close_process',null,(select revision+4 from so_state),jsonb_build_object('contract','selection-process-outcome-1.0.0','outcome','selected','selectedPersonId',m83_id('so-other')));
reset role;
create temp table so_erased_entry as select id from public.position_evaluation_entries where person_id=m83_id('so-other');
delete from public.people where id=m83_id('so-other');
select m83_assert((select closure_outcome='selected' and selected_entry_id is null and organization_id=m83_id('a') from public.position_evaluation_processes where id=(select id from so_state)),'explicit erasure removes selected personal reference without inventing nobody outcome or losing tenant');
select m83_assert(private.selection_process_outcome(m83_id('a'),(select id from so_state))->'selectedPersonId'='null','outcome cannot leak erased selected identity');
select m83_assert(not exists(select 1 from public.position_evaluation_history h where h.entry_id in(select id from so_erased_entry)),'person history respects existing cascade erasure');
insert into public.position_evaluation_processes(organization_id,vacancy_id,name,status,is_current,sequence,start_request_id,created_at)
 select m83_id('a'),m83_id('sp-vac'),'Histórico sintético '||n,'closed',false,n,m83_id('so-page-'||n),now()+n*interval '1 minute' from generate_series(3,58) n;
insert into public.position_evaluation_entries(organization_id,process_id,person_id)
 select organization_id,id,m83_id('person') from public.position_evaluation_processes where vacancy_id=m83_id('sp-vac') and sequence>=3;
set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_assert(jsonb_array_length(public.get_person_selection_history(m83_id('a'),m83_id('person'))->'participations')=50,'person history first page is bounded');
select m83_assert(jsonb_array_length(public.get_person_selection_history(m83_id('a'),m83_id('person'),50)->'participations')>0,'all further participations remain reachable');
select m83_assert(not exists(select 1 from jsonb_array_elements(public.get_person_selection_history(m83_id('a'),m83_id('person'))->'participations') a join jsonb_array_elements(public.get_person_selection_history(m83_id('a'),m83_id('person'),50)->'participations') b on a->>'processId'=b->>'processId'),'person history stable pages do not repeat cycles');
reset role;
select m83_assert(not has_table_privilege('authenticated','public.position_evaluation_processes','update'),'no direct client outcome writes');
select m83_assert(not has_function_privilege('anon','public.get_person_selection_history(uuid,uuid,integer)','execute'),'anonymous cannot read person selection history');
select m83_assert(not has_function_privilege('service_role','public.get_person_selection_history(uuid,uuid,integer)','execute'),'worker cannot read person selection history');
select m83_assert(not has_function_privilege('authenticated','private.selection_process_outcome(uuid,uuid)','execute'),'internal outcome projection not exposed');
